import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._internal();
  static Database? _database;

  // 싱글톤 패턴
  factory DatabaseHelper() => _instance;
  DatabaseHelper._internal();

  // 데이터베이스 getter
  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  // 데이터베이스 초기화
  Future<Database> _initDatabase() async {
    // 데이터베이스 파일 경로
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'my_app.db');

    return await openDatabase(
      path,
      version: 1,
      onCreate: _onCreate,
      onUpgrade: _onUpgrade,
    );
  }

  // 테이블 생성 (최초 1회)
  Future<void> _onCreate(Database db, int version) async {
    // 사용자 테이블
    await db.execute('''
      CREATE TABLE users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        email TEXT UNIQUE NOT NULL,
        created_at TEXT NOT NULL
      )
    ''');

    // 할 일 테이블
    await db.execute('''
      CREATE TABLE todos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        description TEXT,
        is_completed INTEGER DEFAULT 0,
        created_at TEXT NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
      )
    ''');

    // 인덱스 생성 (검색 성능 향상)
    await db.execute('CREATE INDEX idx_todos_user_id ON todos (user_id)');
    await db.execute('CREATE INDEX idx_todos_completed ON todos (is_completed)');
  }

  // 스키마 업그레이드 (버전 변경 시)
  Future<void> _onUpgrade(Database db, int oldVersion, int newVersion) async {
    if (oldVersion < 2) {
      // 버전 2로 업그레이드: 새 컬럼 추가
      await db.execute('ALTER TABLE todos ADD COLUMN priority INTEGER DEFAULT 0');
    }
    if (oldVersion < 3) {
      // 버전 3으로 업그레이드: 새 테이블 추가
      await db.execute('''
        CREATE TABLE categories (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          name TEXT NOT NULL
        )
      ''');
    }
  }

  // 데이터베이스 닫기
  Future<void> close() async {
    final db = await database;
    await db.close();
    _database = null;
  }

  // 데이터베이스 삭제 (테스트/리셋용)
  Future<void> deleteDatabase() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'my_app.db');
    await databaseFactory.deleteDatabase(path);
    _database = null;
  }
}

class Todo {
  final int? id;
  final int userId;
  final String title;
  final String? description;
  final bool isCompleted;
  final DateTime createdAt;

  Todo({
    this.id,
    required this.userId,
    required this.title,
    this.description,
    this.isCompleted = false,
    DateTime? createdAt,
  }) : createdAt = createdAt ?? DateTime.now();

  // Map → 객체 (DB에서 읽을 때)
  factory Todo.fromMap(Map<String, dynamic> map) {
    return Todo(
      id: map['id'] as int,
      userId: map['user_id'] as int,
      title: map['title'] as String,
      description: map['description'] as String?,
      isCompleted: (map['is_completed'] as int) == 1,
      createdAt: DateTime.parse(map['created_at'] as String),
    );
  }

  // 객체 → Map (DB에 쓸 때)
  Map<String, dynamic> toMap() {
    return {
      if (id != null) 'id': id,
      'user_id': userId,
      'title': title,
      'description': description,
      'is_completed': isCompleted ? 1 : 0,
      'created_at': createdAt.toIso8601String(),
    };
  }

  // copyWith 패턴
  Todo copyWith({
    int? id,
    int? userId,
    String? title,
    String? description,
    bool? isCompleted,
    DateTime? createdAt,
  }) {
    return Todo(
      id: id ?? this.id,
      userId: userId ?? this.userId,
      title: title ?? this.title,
      description: description ?? this.description,
      isCompleted: isCompleted ?? this.isCompleted,
      createdAt: createdAt ?? this.createdAt,
    );
  }

  @override
  String toString() {
    return 'Todo(id: $id, title: $title, isCompleted: $isCompleted)';
  }
}

import 'package:sqflite/sqflite.dart';
import '../models/todo.dart';
import 'database_helper.dart';

class TodoDao {
  final DatabaseHelper _dbHelper = DatabaseHelper();

  // ===== CREATE =====

  /// 새 할 일 추가
  Future<int> insert(Todo todo) async {
    final db = await _dbHelper.database;
    return await db.insert(
      'todos',
      todo.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  /// 여러 할 일 일괄 추가 (배치)
  Future<void> insertAll(List<Todo> todos) async {
    final db = await _dbHelper.database;
    final batch = db.batch();

    for (final todo in todos) {
      batch.insert('todos', todo.toMap());
    }

    await batch.commit(noResult: true);
  }

  // ===== READ =====

  /// ID로 조회
  Future<Todo?> getById(int id) async {
    final db = await _dbHelper.database;
    final maps = await db.query(
      'todos',
      where: 'id = ?',
      whereArgs: [id],
      limit: 1,
    );

    if (maps.isEmpty) return null;
    return Todo.fromMap(maps.first);
  }

  /// 모든 할 일 조회
  Future<List<Todo>> getAll() async {
    final db = await _dbHelper.database;
    final maps = await db.query(
      'todos',
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 사용자별 할 일 조회
  Future<List<Todo>> getByUserId(int userId) async {
    final db = await _dbHelper.database;
    final maps = await db.query(
      'todos',
      where: 'user_id = ?',
      whereArgs: [userId],
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 완료/미완료 할 일 조회
  Future<List<Todo>> getByStatus({required bool isCompleted}) async {
    final db = await _dbHelper.database;
    final maps = await db.query(
      'todos',
      where: 'is_completed = ?',
      whereArgs: [isCompleted ? 1 : 0],
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 제목으로 검색
  Future<List<Todo>> search(String keyword) async {
    final db = await _dbHelper.database;
    final maps = await db.query(
      'todos',
      where: 'title LIKE ?',
      whereArgs: ['%$keyword%'],
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 개수 조회
  Future<int> getCount({bool? isCompleted}) async {
    final db = await _dbHelper.database;
    final result = await db.rawQuery(
      isCompleted == null
          ? 'SELECT COUNT(*) as count FROM todos'
          : 'SELECT COUNT(*) as count FROM todos WHERE is_completed = ?',
      isCompleted == null ? [] : [isCompleted ? 1 : 0],
    );

    return Sqflite.firstIntValue(result) ?? 0;
  }

  // ===== UPDATE =====

  /// 할 일 수정
  Future<int> update(Todo todo) async {
    final db = await _dbHelper.database;
    return await db.update(
      'todos',
      todo.toMap(),
      where: 'id = ?',
      whereArgs: [todo.id],
    );
  }

  /// 완료 상태 토글
  Future<int> toggleComplete(int id, bool isCompleted) async {
    final db = await _dbHelper.database;
    return await db.update(
      'todos',
      {'is_completed': isCompleted ? 1 : 0},
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  /// 모두 완료로 표시
  Future<int> markAllComplete(int userId) async {
    final db = await _dbHelper.database;
    return await db.update(
      'todos',
      {'is_completed': 1},
      where: 'user_id = ? AND is_completed = 0',
      whereArgs: [userId],
    );
  }

  // ===== DELETE =====

  /// 할 일 삭제
  Future<int> delete(int id) async {
    final db = await _dbHelper.database;
    return await db.delete(
      'todos',
      where: 'id = ?',
      whereArgs: [id],
    );
  }

  /// 완료된 할 일 모두 삭제
  Future<int> deleteCompleted(int userId) async {
    final db = await _dbHelper.database;
    return await db.delete(
      'todos',
      where: 'user_id = ? AND is_completed = 1',
      whereArgs: [userId],
    );
  }

  /// 사용자의 모든 할 일 삭제
  Future<int> deleteByUserId(int userId) async {
    final db = await _dbHelper.database;
    return await db.delete(
      'todos',
      where: 'user_id = ?',
      whereArgs: [userId],
    );
  }
}

import 'package:sqflite/sqflite.dart';
import 'database_helper.dart';
import '../models/todo.dart';

class AdvancedQueries {
  final DatabaseHelper _dbHelper = DatabaseHelper();

  /// 트랜잭션: 사용자 생성 + 기본 할 일 추가
  Future<int> createUserWithDefaultTodos(String name, String email) async {
    final db = await _dbHelper.database;

    return await db.transaction((txn) async {
      // 1. 사용자 생성
      final userId = await txn.insert('users', {
        'name': name,
        'email': email,
        'created_at': DateTime.now().toIso8601String(),
      });

      // 2. 기본 할 일 추가
      final now = DateTime.now().toIso8601String();
      await txn.insert('todos', {
        'user_id': userId,
        'title': '앱 둘러보기',
        'description': '앱의 기능을 살펴보세요!',
        'is_completed': 0,
        'created_at': now,
      });

      await txn.insert('todos', {
        'user_id': userId,
        'title': '프로필 설정하기',
        'description': '프로필을 완성해보세요.',
        'is_completed': 0,
        'created_at': now,
      });

      // 에러 발생 시 모든 작업 롤백
      // throw Exception('테스트 에러'); // 주석 해제하면 롤백 테스트 가능

      return userId;
    });
  }

  /// JOIN 쿼리: 사용자별 할 일 통계
  Future<List<Map<String, dynamic>>> getUserTodoStats() async {
    final db = await _dbHelper.database;

    return await db.rawQuery('''
      SELECT 
        u.id as user_id,
        u.name as user_name,
        COUNT(t.id) as total_todos,
        SUM(CASE WHEN t.is_completed = 1 THEN 1 ELSE 0 END) as completed_todos,
        SUM(CASE WHEN t.is_completed = 0 THEN 1 ELSE 0 END) as pending_todos
      FROM users u
      LEFT JOIN todos t ON u.id = t.user_id
      GROUP BY u.id
      ORDER BY total_todos DESC
    ''');
  }

  /// 페이지네이션
  Future<List<Todo>> getTodosPaginated({
    required int page,
    int pageSize = 20,
    int? userId,
  }) async {
    final db = await _dbHelper.database;
    final offset = (page - 1) * pageSize;

    String whereClause = '';
    List<dynamic> whereArgs = [];

    if (userId != null) {
      whereClause = 'WHERE user_id = ?';
      whereArgs = [userId];
    }

    final maps = await db.rawQuery('''
      SELECT * FROM todos
      $whereClause
      ORDER BY created_at DESC
      LIMIT ? OFFSET ?
    ''', [...whereArgs, pageSize, offset]);

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 날짜 범위로 조회
  Future<List<Todo>> getTodosByDateRange({
    required DateTime startDate,
    required DateTime endDate,
  }) async {
    final db = await _dbHelper.database;

    final maps = await db.query(
      'todos',
      where: 'created_at BETWEEN ? AND ?',
      whereArgs: [
        startDate.toIso8601String(),
        endDate.toIso8601String(),
      ],
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 전체 텍스트 검색 (제목 + 설명)
  Future<List<Todo>> fullTextSearch(String query) async {
    final db = await _dbHelper.database;
    final searchPattern = '%$query%';

    final maps = await db.query(
      'todos',
      where: 'title LIKE ? OR description LIKE ?',
      whereArgs: [searchPattern, searchPattern],
      orderBy: 'created_at DESC',
    );

    return maps.map((map) => Todo.fromMap(map)).toList();
  }

  /// 집계 쿼리
  Future<Map<String, int>> getTodoSummary(int userId) async {
    final db = await _dbHelper.database;

    final result = await db.rawQuery('''
      SELECT 
        COUNT(*) as total,
        SUM(CASE WHEN is_completed = 1 THEN 1 ELSE 0 END) as completed,
        SUM(CASE WHEN is_completed = 0 THEN 1 ELSE 0 END) as pending
      FROM todos
      WHERE user_id = ?
    ''', [userId]);

    final row = result.first;
    return {
      'total': row['total'] as int? ?? 0,
      'completed': row['completed'] as int? ?? 0,
      'pending': row['pending'] as int? ?? 0,
    };
  }

  /// 배치 업데이트
  Future<void> batchUpdatePriority(List<Map<String, int>> updates) async {
    final db = await _dbHelper.database;
    final batch = db.batch();

    for (final update in updates) {
      batch.update(
        'todos',
        {'priority': update['priority']},
        where: 'id = ?',
        whereArgs: [update['id']],
      );
    }

    await batch.commit();
  }
}

